from math import log, log2

K_B: float = 1.380649e-23

def prefix_audit(input_bits: int, retained_bits: int, temperature: float) -> tuple[float, float]:
    if not 0 <= retained_bits <= input_bits:
        raise ValueError("invalid retained-bit count")
    erased = log2(2 ** input_bits) - log2(2 ** retained_bits)
    return erased, erased * K_B * temperature * log(2.0)

def main() -> None:
    for n, retained in [(16, 4), (32, 8), (64, 16), (128, 32)]:
        bits, joules = prefix_audit(n, retained, 300.0)
        print(f"n={n:3d}, retained={retained:2d}, erased={bits:5.1f}, cost={joules:.6e} J")

if __name__ == "__main__":
    main()

from math import log
from typing import Callable, Iterable

K_B: float = 1.380649e-23

def workload(sizes: Iterable[int], bound: Callable[[int], float], temperature: float) -> tuple[float, float]:
    total_bits = sum(bound(n) for n in sizes)
    return total_bits, total_bits * K_B * temperature * log(2.0)

def main() -> None:
    for limit in (10, 100, 1000, 10000):
        bits, energy = workload(range(1, limit + 1), lambda n: n / 2.0, 300.0)
        expected = limit * (limit + 1) / 4.0
        assert bits == expected
        print(f"N={limit:5d}: {bits:12.1f} bits, {energy:.6e} J")

if __name__ == "__main__":
    main()

