from math import log2
from typing import Callable, Hashable, Iterable, TypeVar
X = TypeVar("X")
Y = TypeVar("Y", bound=Hashable)

def image_cardinality_erasure(inputs: Iterable[X], f: Callable[[X], Y]) -> float:
    domain = tuple(inputs)
    if not domain:
        raise ValueError("domain must be nonempty")
    image = {f(x) for x in domain}
    return log2(len(domain)) - log2(len(image))

from math import log
from typing import Callable, Iterable

def workload_energy_bound(sizes: Iterable[int], b: Callable[[int], float], k_b: float, temperature: float) -> float:
    if k_b < 0 or temperature < 0:
        raise ValueError("physical parameters must be nonnegative")
    return sum(b(n) for n in sizes) * k_b * temperature * log(2.0)

from math import floor, log

def linear_threshold_witness(energy: float, rate: float, k_b: float, temperature: float) -> int:
    factor = rate * k_b * temperature * log(2.0)
    if factor <= 0:
        raise ValueError("rate, k_b, and temperature must be positive")
    return floor(energy / factor) + 1

